import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"武林外传","description":"七侠镇同福客栈聚集了一群各有过去、能力与弱点的人。掌柜、跑堂、杂役、账房和厨子努力维持日常生活，却总被江湖传闻、陌生来客与自己的小心思卷入麻烦。","frontmatter":{"title":"武林外传","description":"七侠镇同福客栈聚集了一群各有过去、能力与弱点的人。掌柜、跑堂、杂役、账房和厨子努力维持日常生活，却总被江湖传闻、陌生来客与自己的小心思卷入麻烦。","media":{"category":"series","year":2006,"doubanRating":9.6,"ratingCheckedAt":"2026-10-31","ratingSource":"https://www.douban.com/doulist/134440083/","ratingSourceType":"豆瓣公开片单"},"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"影视导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"影视 · 电视剧","summary":"七侠镇同福客栈聚集了一群各有过去、能力与弱点的人。掌柜、跑堂、杂役、账房和厨子努力维持日常生活，却总被江湖传闻、陌生来客与自己的小心思卷入麻烦。","status":"active","related":[{"title":"大明王朝1566","link":"/life/personal/media/series/ming-dynasty-1566","kind":"影视导读","scope":"general","audience":"general"},{"title":"是，大臣 第一季","link":"/life/personal/media/series/yes-minister-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"红楼梦（1987）","link":"/life/personal/media/series/dream-of-the-red-chamber-1987","kind":"影视导读","scope":"general","audience":"general"},{"title":"西游记（1986）","link":"/life/personal/media/series/journey-to-the-west-1986","kind":"影视导读","scope":"general","audience":"general"},{"title":"老友记 第一季","link":"/life/personal/media/series/friends-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"请回答1988","link":"/life/personal/media/series/reply-1988","kind":"影视导读","scope":"general","audience":"general"},{"title":"白色巨塔（2003）","link":"/life/personal/media/series/the-white-tower-2003","kind":"影视导读","scope":"general","audience":"general"},{"title":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale","kind":"影视导读","scope":"general","audience":"general"},{"title":"我的团长我的团","link":"/life/personal/media/series/my-chief-and-my-regiment","kind":"影视导读","scope":"general","audience":"general"},{"title":"非自然死亡","link":"/life/personal/media/series/unnatural","kind":"影视导读","scope":"general","audience":"general"},{"title":"机智医生生活 第一季","link":"/life/personal/media/series/hospital-playlist-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"亮剑","link":"/life/personal/media/series/bright-sword","kind":"影视导读","scope":"general","audience":"general"},{"title":"琅琊榜","link":"/life/personal/media/series/nirvana-in-fire","kind":"影视导读","scope":"general","audience":"general"},{"title":"后宫·甄嬛传","link":"/life/personal/media/series/empresses-in-the-palace","kind":"影视导读","scope":"general","audience":"general"},{"title":"漫长的季节","link":"/life/personal/media/series/the-long-season","kind":"影视导读","scope":"general","audience":"general"},{"title":"我们与恶的距离","link":"/life/personal/media/series/the-world-between-us","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale"},"next":{"text":"我的团长我的团","link":"/life/personal/media/series/my-chief-and-my-regiment"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale"},"next":{"text":"我的团长我的团","link":"/life/personal/media/series/my-chief-and-my-regiment"}},"headers":[],"relativePath":"life/personal/media/series/my-own-swordsman.md","filePath":"life/personal/media/series/my-own-swordsman.md"}'),n={name:"life/personal/media/series/my-own-swordsman.md"};function l(s,e,o,d,p,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="武林外传" tabindex="-1">武林外传 <a class="header-anchor" href="#武林外传" aria-label="Permalink to &quot;武林外传&quot;">​</a></h1><p><a href="./../overview">影视总览</a> · <a href="./overview">电视剧片单</a></p><h2 id="基本资料" tabindex="-1">基本资料 <a class="header-anchor" href="#基本资料" aria-label="Permalink to &quot;基本资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td>原名 / 别名</td><td>My Own Swordsman</td></tr><tr><td>年份 / 地区</td><td>2006 / 中国大陆</td></tr><tr><td>类型</td><td>情景喜剧 / 武侠 / 古装</td></tr><tr><td>导演 / 主创</td><td>尚敬；编剧宁财神</td></tr><tr><td>主要演员 / 配音</td><td>闫妮、姚晨、沙溢、喻恩泰、姜超、倪虹洁</td></tr><tr><td>篇幅 / 版本</td><td>80 集，单集约 48 分钟</td></tr><tr><td>豆瓣参考评分</td><td><strong>9.6 / 10</strong></td></tr><tr><td>评分依据</td><td><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>（豆瓣公开片单）</td></tr><tr><td>查询日期</td><td>2026-10-31</td></tr></tbody></table><p>评分为本次查询可读取的豆瓣页面值，网页缓存可能滞后，不能保证与此刻实时值一致。 篇幅按常见版本作近似说明，片头、花絮及剪辑差异可能影响播放时长。</p><h2 id="创作背景与资料" tabindex="-1">创作背景与资料 <a class="header-anchor" href="#创作背景与资料" aria-label="Permalink to &quot;创作背景与资料&quot;">​</a></h2><p>尚敬的回顾访谈与有关创作往事的报道，呈现了这部古装情景喜剧如何把武侠经验、当时生活和固定客栈空间结合起来。作品与制作年代的电视、广告和流行语言关系密切，许多今天不易理解的梗有明确语境。<a href="https://m.ahradio.com.cn/yulenews/143820.html" target="_blank" rel="noopener noreferrer">尚敬深度访谈</a>、<a href="https://www.thepaper.cn/newsDetail_forward_11678878" target="_blank" rel="noopener noreferrer">创作往事回顾</a></p><p>它最持久的部分却不是追逐热点，而是让一群不够成功的人，学会在共同生活中维持体面和关系。</p><h2 id="剧情介绍" tabindex="-1">剧情介绍 <a class="header-anchor" href="#剧情介绍" aria-label="Permalink to &quot;剧情介绍&quot;">​</a></h2><p>七侠镇同福客栈聚集了一群各有过去、能力与弱点的人。掌柜、跑堂、杂役、账房和厨子努力维持日常生活，却总被江湖传闻、陌生来客与自己的小心思卷入麻烦。</p><p>剧集借古装外壳讨论非常现代的工作、消费、关系与自我评价问题。所谓江湖并不总在远方，很多冲突就发生在一张饭桌、一份工资和一次争执里。</p><h2 id="特色与看点" tabindex="-1">特色与看点 <a class="header-anchor" href="#特色与看点" aria-label="Permalink to &quot;特色与看点&quot;">​</a></h2><h3 id="_1-叙事与人物" tabindex="-1">1. 叙事与人物 <a class="header-anchor" href="#_1-叙事与人物" aria-label="Permalink to &quot;1. 叙事与人物&quot;">​</a></h3><p>方言、流行文化戏仿与武侠套路形成多层笑点，但人物能够长期成立，依靠的是每个人都希望被理解，又不断暴露自己的局限。</p><h3 id="_2-主题与表达" tabindex="-1">2. 主题与表达 <a class="header-anchor" href="#_2-主题与表达" aria-label="Permalink to &quot;2. 主题与表达&quot;">​</a></h3><p>许多单集会把一个道理先推到荒诞处，再回到人与人的实际相处。可观察它怎样用反英雄的方式讨论勇敢、责任和普通人的体面。</p><h2 id="客栈里的角色怎样互相需要" tabindex="-1">客栈里的角色怎样互相需要 <a class="header-anchor" href="#客栈里的角色怎样互相需要" aria-label="Permalink to &quot;客栈里的角色怎样互相需要&quot;">​</a></h2><p>佟湘玉既精明又害怕失去，白展堂有能力却想摆脱过去，郭芙蓉带着英雄想象进入普通劳动，吕秀才用学问支撑自尊，李大嘴渴望被认可，祝无双则不断面对归属感问题。莫小贝与捕快们又把教育和地方秩序引进来。</p><p>每个人都可能自私、胆怯或好面子，喜剧并不要求他们永远高尚。真正使群体成立的，是某人犯错之后，其他人能否一边设限，一边保留他回来的位置。</p><h2 id="武侠为什么落在工资和家务里" tabindex="-1">武侠为什么落在工资和家务里 <a class="header-anchor" href="#武侠为什么落在工资和家务里" aria-label="Permalink to &quot;武侠为什么落在工资和家务里&quot;">​</a></h2><p>传统江湖故事常以远行、决斗和扬名推进，本剧却让角色被账本、劳动和琐事拴在一起。想做大侠的人先要扫地，曾经有名的人也得解释自己的日常责任；英雄想象因此不断受到现实生活检验。</p><p>许多来客把某种极端观念带入客栈，例如唯钱、唯名或不受约束的自由。单集让观念充分发展到荒诞，再检验它会怎样伤害具体关系。</p><h2 id="观看台词之外的表演" tabindex="-1">观看台词之外的表演 <a class="header-anchor" href="#观看台词之外的表演" aria-label="Permalink to &quot;观看台词之外的表演&quot;">​</a></h2><p>人物在群戏里常有同时发生的小反应：有人努力维持局面，有人已经识破，却等着看热闹。镜头未切给说话者时，旁边人的动作也在讲故事。方言与节奏差异进一步增加角色辨识度。</p><p>重看一个熟悉单集，可先注意不起主要冲突的人怎样参与，常能发现群像并不是主角说话、其他人等待的轮流表演。</p><h2 id="评价与重温建议" tabindex="-1">评价与重温建议 <a class="header-anchor" href="#评价与重温建议" aria-label="Permalink to &quot;评价与重温建议&quot;">​</a></h2><p>本剧的长处是把严肃问题放进轻快语言，同时允许角色保留缺点。局限是单集质量、年代笑点及说教力度并不均匀，有些讽刺今天会产生不同感受。</p><p>可以先从认识人物的前几集开始，再挑主题感兴趣的单元；不必要求每一句都成为人生道理。它对普通生活的耐心，往往比那些被单独截出来的名句更能说明为什么值得长期重看。</p><h2 id="适合谁看与观看建议" tabindex="-1">适合谁看与观看建议 <a class="header-anchor" href="#适合谁看与观看建议" aria-label="Permalink to &quot;适合谁看与观看建议&quot;">​</a></h2><p>适合喜欢对白、群像与生活化幽默的人。既可按顺序观看，也可在熟悉人物后选择单集；某些梗依赖当年的影视和网络语境，今天观看时可保留距离。</p><h2 id="看后思考" tabindex="-1">看后思考 <a class="header-anchor" href="#看后思考" aria-label="Permalink to &quot;看后思考&quot;">​</a></h2><p>同福客栈为什么像一个临时家庭？作品如何重新解释武侠故事中的英雄和江湖？</p><p>创作事实见段落所附来源；人物、场景与评价部分为本站观影分析，不代表主创唯一解释。正文保留主要故事体验，不展开关键结局。评分用于辅助选片，不代表每位观众的感受。</p><h2 id="资料与复核入口" tabindex="-1">资料与复核入口 <a class="header-anchor" href="#资料与复核入口" aria-label="Permalink to &quot;资料与复核入口&quot;">​</a></h2><ul><li><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>：本页评分依据；查询于 2026-10-31。</li><li><a href="https://movie.douban.com/subject/3882715/" target="_blank" rel="noopener noreferrer">《武林外传》豆瓣条目</a>：版本与后续评分复核入口；部分条目可能要求验证。</li></ul><p><a href="./overview">返回电视剧片单</a> · <a href="./../overview">返回影视总览</a></p>',36)])])}const u=a(n,[["render",l]]);export{m as __pageData,u as default};
